import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"分阶段实施计划","description":"","frontmatter":{"title":"分阶段实施计划"},"headers":[],"relativePath":"zh/guide/roadmap.md","filePath":"zh/guide/roadmap.md","lastUpdated":0}`),a={name:`zh/guide/roadmap.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_14-分阶段实施计划" tabindex="-1">14. 分阶段实施计划 <a class="header-anchor" href="#_14-分阶段实施计划" aria-label="Permalink to “14. 分阶段实施计划”">​</a></h1><h2 id="p0-核心恢复引擎" tabindex="-1">P0：核心恢复引擎 <a class="header-anchor" href="#p0-核心恢复引擎" aria-label="Permalink to “P0：核心恢复引擎”">​</a></h2><p>目标：先实现完整且可测试的恢复闭环，不接入复杂网络能力。</p><p>实现内容：</p><ol><li>Cargo Workspace。</li><li>Resource、Dependency、Evidence、Diagnosis、RecoveryPolicy、RecoveryRun 等领域模型。</li><li>配置解析和验证。</li><li>依赖图构建和循环检测。</li><li>Process Probe。</li><li>Exec Probe。</li><li>连续失败阈值和健康状态转换。</li><li>RecoveryRun 状态机。</li><li>有序候选动作。</li><li>恢复动作执行后重新验证。</li><li>失败后的重新诊断。</li><li>超时、预算和冷却时间。</li><li>资源级恢复互斥。</li><li>SQLite 持久化。</li><li>崩溃恢复和未知结果处理。</li><li>CLI 基础命令。</li><li>结构化日志与审计事件。</li><li>集成测试与故障注入。</li></ol><p>P0 不包含：</p><ul><li>HTTP Probe。</li><li>Web Dashboard。</li><li>远程管理 API。</li><li>插件市场。</li><li>OpenClash。</li><li>复杂 Wi-Fi 恢复。</li><li>企业通知平台。</li></ul><p>验收标准：</p><ul><li>一个进程退出后能被检测。</li><li>一个受控命令失败后能触发恢复。</li><li>第一个恢复方案失败时能选择第二个方案。</li><li>命令返回成功但资源仍异常时，不得报告恢复成功。</li><li>依赖不健康时，上层动作不会提前执行。</li><li>同一资源不会并发执行多个恢复任务。</li><li>Custos 崩溃重启后可以恢复未完成任务。</li><li>结果未知的动作不会被无条件重复执行。</li><li>所有状态转换都可以通过日志和数据库追溯。</li><li>所有预算耗尽的任务都能明确终止。</li></ul><h2 id="p1-插件运行时与通知基础设施" tabindex="-1">P1：插件运行时与通知基础设施 <a class="header-anchor" href="#p1-插件运行时与通知基础设施" aria-label="Permalink to “P1：插件运行时与通知基础设施”">​</a></h2><p>实现内容：</p><ol><li>JSON-RPC 2.0 stdio 插件协议。</li><li>插件能力声明。</li><li>插件启动、关闭和重启管理。</li><li>超时、取消和输出限制。</li><li>插件崩溃隔离。</li><li>NotificationEvent。</li><li>本地日志渠道。</li><li>Webhook 内置渠道。</li><li>SMTP 内置渠道。</li><li>持久化通知队列。</li><li>通知重试、去重和死信状态。</li><li>CLI 通知状态和重试命令。</li><li>插件权限与能力检查。</li></ol><p>验收标准：</p><ul><li>插件崩溃不会导致核心进程退出。</li><li>大量 stderr 输出不会阻塞协议通信。</li><li>插件无响应会在规定时间内超时。</li><li>断网期间通知保留在本地队列。</li><li>网络恢复后通知可以继续发送。</li><li>通知发送失败不影响恢复任务。</li><li>敏感字段不会进入普通日志。</li></ul><h2 id="p2-平台基础能力" tabindex="-1">P2：平台基础能力 <a class="header-anchor" href="#p2-平台基础能力" aria-label="Permalink to “P2：平台基础能力”">​</a></h2><p>优先支持 Linux 和 Windows。</p><p>实现内容：</p><ul><li>进程管理。</li><li>systemd 服务控制。</li><li>Windows Service 控制。</li><li>平台能力探测。</li><li>平台权限检查。</li><li>系统重启动作。</li><li>本机网络基础探测。</li><li>平台适配器集成测试。</li></ul><p>验收标准：</p><ul><li>Linux 不使用 systemd 时能正确报告能力不支持，而不是误执行。</li><li>Windows 服务操作具备超时和结果验证。</li><li>高风险操作没有明确授权时会被拒绝。</li><li>平台特有错误能转换为统一的故障结果。</li></ul><h2 id="p3-网络、代理与真实自愈场景" tabindex="-1">P3：网络、代理与真实自愈场景 <a class="header-anchor" href="#p3-网络、代理与真实自愈场景" aria-label="Permalink to “P3：网络、代理与真实自愈场景”">​</a></h2><p>实现内容：</p><ul><li>网络接口探测。</li><li>网关和路由探测。</li><li>DNS 探测。</li><li>HTTP Probe。</li><li>代理连接与认证诊断。</li><li>Mihomo 插件。</li><li>cloudflared 插件。</li><li>Windows Wi-Fi 恢复。</li><li>OpenWrt 网络适配器。</li><li>OpenClash 插件。</li><li>网络恢复后的端到端验证。</li><li>网络操作的互斥与风险控制。</li></ul><p>验收场景：</p><ol><li>向日葵离线，但网络正常：只恢复向日葵相关服务。</li><li>Wi-Fi 断开：先恢复网络，再验证远程管理能力。</li><li>代理正常、Tunnel 异常：重启 Tunnel。</li><li>代理异常、Tunnel 异常：先恢复代理，再处理 Tunnel。</li><li>代理返回 407：识别认证问题，不直接认定服务宕机。</li><li>代理恢复后 Tunnel 仍异常：重新诊断 Tunnel。</li><li>所有恢复方案失败：停止自动处理并通知。</li><li>恢复期间网络再次断开：本地引擎继续运行并持久化结果。</li></ol><h2 id="p4-可选管理界面与扩展" tabindex="-1">P4：可选管理界面与扩展 <a class="header-anchor" href="#p4-可选管理界面与扩展" aria-label="Permalink to “P4：可选管理界面与扩展”">​</a></h2><p>实现内容：</p><ul><li>Web Dashboard，默认关闭。</li><li>资源列表与健康状态。</li><li>依赖图展示。</li><li>RecoveryRun 时间线。</li><li>通知状态。</li><li>配置检查。</li><li>更丰富的通知插件。</li><li>macOS 适配。</li><li>BSD 适配。</li><li>OpenWrt 完整能力。</li><li>插件签名与分发策略。</li><li>更完善的操作授权界面。</li></ul><p>验收标准：</p><ul><li>Dashboard 默认关闭时无监听端口。</li><li>Dashboard 不可用时核心功能不受影响。</li><li>Dashboard 不直接执行绕过 Core Engine 的动作。</li><li>高风险操作仍经过统一权限和审计流程。</li></ul><hr><h2 id="落地跟踪" tabindex="-1">落地跟踪 <a class="header-anchor" href="#落地跟踪" aria-label="Permalink to “落地跟踪”">​</a></h2><p>每个阶段落地后以 commit hash 勾掉；来源与验收口径见上文对应阶段。</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> P0 核心恢复引擎（commit: __）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> P1 插件运行时与通知基础设施（commit: __）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> P2 平台基础能力（commit: __）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> P3 网络、代理与真实自愈场景（commit: __）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> P4 可选管理界面与扩展（commit: __）</label></li></ul>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};